	if (!m_stickySpeedKey && InputBindings.thrustForward->IsActive()) {
		float itval = InputBindings.thrustForward->GetValue() * linearThrustPower;
		power.z = fabs(itval);
		double strafeZ = 0.0;
		if (GetCruiseDirection() == CRUISE_FWD) {
